# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: emit
def emit(xs, factor=10):
    return [v * factor for v in xs]

# region: shape
def shape(xs, factor=10):
    return [v * factor for v in xs]

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs[1:]]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return fold(digest(intake(shape(emit(sift(raw))))))

